/* Query 1: Data cleaning */ SELECT REF_DATE, GEO, "Household income", "Energy type", VALUE, STATUS FROM "StatCan Data" WHERE "Energy consumption" = 'Gigajoules per household' AND (STATUS IS NULL OR STATUS != 'F') AND VALUE IS NOT NULL; /* Query 2: Average by province */ SELECT GEO, ROUND(AVG(VALUE), 1) AS avg_gj_per_household FROM "StatCan Data" WHERE "Energy consumption" = 'Gigajoules per household' AND (STATUS IS NULL OR STATUS != 'F') AND VALUE IS NOT NULL AND GEO != 'Canada' GROUP BY GEO ORDER BY avg_gj_per_household DESC; /* Query 3: JOIN by region with population */ SELECT r.Region, ROUND(AVG(s.VALUE), 1) AS avg_gj_per_household, (SELECT SUM(CAST(REPLACE(Population_2026, ',', '') AS REAL)) FROM "Regions of Canada" WHERE Region = r.Region) AS total_population FROM "StatCan Data" s JOIN "Regions of Canada" r ON s.GEO = r.Province_name WHERE s."Energy consumption" = 'Gigajoules per household' AND (s.STATUS IS NULL OR s.STATUS != 'F') AND s.VALUE IS NOT NULL GROUP BY r.Region ORDER BY avg_gj_per_household DESC; /* Query 4: Window function ranking within region */ SELECT r.Region, s.GEO, ROUND(AVG(s.VALUE), 1) AS avg_gj_per_household, RANK() OVER (PARTITION BY r.Region ORDER BY AVG(s.VALUE) DESC) AS rank_in_region FROM "StatCan Data" s JOIN "Regions of Canada" r ON s.GEO = r.Province_name WHERE s."Energy consumption" = 'Gigajoules per household' AND (s.STATUS IS NULL OR s.STATUS != 'F') AND s.VALUE IS NOT NULL GROUP BY r.Region, s.GEO ORDER BY r.Region, rank_in_region; /* Query 5: CTE comparing each province to national benchmark */ WITH national_avg AS (SELECT AVG(VALUE) AS canada_avg FROM "StatCan Data" WHERE "Energy consumption" = 'Gigajoules per household' AND GEO = 'Canada' AND (STATUS IS NULL OR STATUS != 'F') AND VALUE IS NOT NULL) SELECT s.GEO, ROUND(AVG(s.VALUE), 1) AS province_avg, ROUND((SELECT canada_avg FROM national_avg), 1) AS national_benchmark, ROUND(AVG(s.VALUE) - (SELECT canada_avg FROM national_avg), 1) AS difference_from_national FROM "StatCan Data" s WHERE s."Energy consumption" = 'Gigajoules per household' AND (s.STATUS IS NULL OR s.STATUS != 'F') AND s.VALUE IS NOT NULL AND s.GEO != 'Canada' GROUP BY s.GEO ORDER BY difference_from_national DESC;